reset.definition:
{
  "StartAt" : "StopInitializeWorkflow",
  "States" : {
    "PrepareSwitch" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StopSetPreconditionFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StopSetDesiredStopped",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "prepare_reset",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.switch_prepared",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetCleanupCheck" : {
      "Next" : "ResetCleanupDone",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "check_reset_cleanup",
          "command_id.$" : "$.reset_command.Payload.command_id",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reset_check",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetCleanupDone" : {
      "Choices" : [ {
        "BooleanEquals" : true,
        "Next" : "StartMarkSucceeded",
        "Variable" : "$.reset_check.Payload.complete"
      } ],
      "Default" : "ResetCleanupWait",
      "Type" : "Choice"
    },
    "ResetCleanupRenew" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StopSetPreconditionFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "ResetCleanupCheck",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "renew",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.switch_prepared",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetCleanupSend" : {
      "Next" : "ResetCleanupWait",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "run_reset_cleanup",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reset_command",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetCleanupWait" : {
      "Next" : "ResetCleanupRenew",
      "Seconds" : 15,
      "Type" : "Wait"
    },
    "ResetCommit" : {
      "Next" : "StartReconcileBeforeStart",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "commit_reset",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.switch_prepared",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetPrepareCheck" : {
      "Catch" : [ {
        "ErrorEquals" : [ "ResetPreparationFailed" ],
        "Next" : "StopSetHostFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "ResetPrepareDone",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "check_reset_prepare",
          "command_id.$" : "$.reset_command.Payload.command_id",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reset_check",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetPrepareDone" : {
      "Choices" : [ {
        "BooleanEquals" : true,
        "Next" : "ResetCommit",
        "Variable" : "$.reset_check.Payload.complete"
      } ],
      "Default" : "ResetPrepareWait",
      "Type" : "Choice"
    },
    "ResetPrepareRenew" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StopSetPreconditionFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "ResetPrepareCheck",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "renew",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.switch_prepared",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetPrepareSend" : {
      "Next" : "ResetPrepareWait",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-stop-task",
        "Payload" : {
          "action" : "run_reset_prepare",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reset_command",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "ResetPrepareWait" : {
      "Next" : "ResetPrepareRenew",
      "Seconds" : 15,
      "Type" : "Wait"
    },
    "StartAlreadyReady" : {
      "Choices" : [ {
        "BooleanEquals" : true,
        "Next" : "StartUpdateDnsRecord",
        "Variable" : "$.desired.Payload.already_ready"
      } ],
      "Default" : "StartRunStartScript",
      "Type" : "Choice"
    },
    "StartCheckDnsChange" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetEndpointFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartDnsChangeInSync",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "check_dns_change",
          "change_id.$" : "$.dns_change.Payload.change_id",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.dns_check",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartCheckHostStart" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetHostFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartHostStartComplete",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "check_host_start",
          "command_id.$" : "$.host_start.Payload.command_id",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.host_check",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartDnsChangeInSync" : {
      "Choices" : [ {
        "BooleanEquals" : true,
        "Next" : "StartReconcileDns",
        "Variable" : "$.dns_check.Payload.complete"
      } ],
      "Default" : "StartWaitDnsInSync",
      "Type" : "Choice"
    },
    "StartDnsPollWithinDeadline" : {
      "Choices" : [ {
        "Next" : "StartSetEndpointFailure",
        "NumericGreaterThanEquals" : 4,
        "Variable" : "$.dns_poll.count"
      } ],
      "Default" : "StartRenewBeforeDnsProbe",
      "Type" : "Choice"
    },
    "StartEndpointReady" : {
      "Choices" : [ {
        "Next" : "ResetCleanupSend",
        "StringEquals" : "HEALTHY",
        "Variable" : "$.reconcile.state.health"
      } ],
      "Default" : "StartWaitDnsInSync",
      "Type" : "Choice"
    },
    "StartHostPollWithinDeadline" : {
      "Choices" : [ {
        "Next" : "StartSetHostTimeout",
        "NumericGreaterThanEquals" : 24,
        "Variable" : "$.host_poll.count"
      } ],
      "Default" : "StartRenewBeforeHostCheck",
      "Type" : "Choice"
    },
    "StartHostStartComplete" : {
      "Choices" : [ {
        "BooleanEquals" : true,
        "Next" : "StartInitReadyPoll",
        "Variable" : "$.host_check.Payload.complete"
      } ],
      "Default" : "StartWaitHostStart",
      "Type" : "Choice"
    },
    "StartIncrementDnsPoll" : {
      "Next" : "StartDnsPollWithinDeadline",
      "Parameters" : {
        "count.$" : "States.MathAdd($.dns_poll.count, 1)"
      },
      "ResultPath" : "$.dns_poll",
      "Type" : "Pass"
    },
    "StartIncrementHostPoll" : {
      "Next" : "StartHostPollWithinDeadline",
      "Parameters" : {
        "count.$" : "States.MathAdd($.host_poll.count, 1)"
      },
      "ResultPath" : "$.host_poll",
      "Type" : "Pass"
    },
    "StartIncrementReadyPoll" : {
      "Next" : "StartReadyPollWithinDeadline",
      "Parameters" : {
        "count.$" : "States.MathAdd($.ready_poll.count, 1)"
      },
      "ResultPath" : "$.ready_poll",
      "Type" : "Pass"
    },
    "StartInitDnsPoll" : {
      "Next" : "StartWaitDnsInSync",
      "Result" : {
        "count" : 0
      },
      "ResultPath" : "$.dns_poll",
      "Type" : "Pass"
    },
    "StartInitHostPoll" : {
      "Next" : "StartWaitHostStart",
      "Result" : {
        "count" : 0
      },
      "ResultPath" : "$.host_poll",
      "Type" : "Pass"
    },
    "StartInitReadyPoll" : {
      "Next" : "StartWaitReady",
      "Result" : {
        "count" : 0
      },
      "ResultPath" : "$.ready_poll",
      "Type" : "Pass"
    },
    "StartMarkSucceeded" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetEndpointFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "End" : true,
      "OutputPath" : "$.Payload",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "complete",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartReadyPollWithinDeadline" : {
      "Choices" : [ {
        "Next" : "StartSetReadyTimeout",
        "NumericGreaterThanEquals" : 5,
        "Variable" : "$.ready_poll.count"
      } ],
      "Default" : "StartRenewBeforeReadyProbe",
      "Type" : "Choice"
    },
    "StartReconcileAfterFailure" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartUnrecoverableFailure"
      } ],
      "Next" : "StartRecordFailure",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-reconcile",
        "Payload" : {
          "operation" : "reconcile",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.failure_reconcile",
      "Type" : "Task"
    },
    "StartReconcileBeforeStart" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetObservationFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartSetDesiredRunning",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-reconcile",
        "Payload" : {
          "operation" : "reconcile",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reconcile",
      "ResultSelector" : {
        "state.$" : "$.Payload"
      },
      "Type" : "Task"
    },
    "StartReconcileDns" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetObservationFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartEndpointReady",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-reconcile",
        "Payload" : {
          "operation" : "reconcile",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reconcile",
      "ResultSelector" : {
        "state.$" : "$.Payload"
      },
      "Type" : "Task"
    },
    "StartReconcileReady" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetObservationFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartRuntimeReady",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-reconcile",
        "Payload" : {
          "operation" : "reconcile",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.reconcile",
      "ResultSelector" : {
        "state.$" : "$.Payload"
      },
      "Type" : "Task"
    },
    "StartRecordFailure" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartUnrecoverableFailure"
      } ],
      "Next" : "StartStartFailed",
      "OutputPath" : "$.Payload",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "fail",
          "error_code.$" : "$.failure.error_code",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "workflow_error.$" : "$.workflow_error"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartRenewBeforeDnsProbe" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetLockLostFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartCheckDnsChange",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "renew",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.lease",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartRenewBeforeHostCheck" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetLockLostFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartCheckHostStart",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "renew",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.lease",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartRenewBeforeReadyProbe" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetLockLostFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartReconcileReady",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "renew",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.lease",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartRunStartScript" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetHostFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartInitHostPoll",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "run_host_start",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.host_start",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartRuntimeReady" : {
      "Choices" : [ {
        "BooleanEquals" : true,
        "Next" : "StartUpdateDnsRecord",
        "Variable" : "$.reconcile.state.observation.runtime_ready"
      } ],
      "Default" : "StartWaitReady",
      "Type" : "Choice"
    },
    "StartSetDesiredRunning" : {
      "Catch" : [ {
        "ErrorEquals" : [ "States.ALL" ],
        "Next" : "StartSetPreconditionFailure",
        "ResultPath" : "$.workflow_error"
      } ],
      "Next" : "StartAlreadyReady",
      "OutputPath" : "$",
      "Parameters" : {
        "FunctionName" : "arn:aws:lambda:ap-northeast-1:385526546525:function:wc-dev-start-task",
        "Payload" : {
          "action" : "set_desired",
          "lease_id.$" : "$.lease_id",
          "operation_id.$" : "$.operation_id",
          "schema_version" : 1,
          "state.$" : "$.reconcile.state"
        }
      },
      "Resource" : "arn:aws:states:::lambda:invoke",
      "ResultPath" : "$.desired",
      "Retry" : [ {
        "BackoffRate" : 2,
        "ErrorEquals" : [ "Lambda.ServiceException", "Lambda.TooManyRequestsException" ],
        "IntervalSeconds" : 2,
        "MaxAttempts" : 3
      } ],
      "Type" : "Task"
    },
    "StartSetEndpointFailure" : {
      "Next" : "StartReconcileAfterFailure",
      "Result" : {
        "error_code" : "ENDPOINT_DISCREPANCY"
      },
      "ResultPath" : "$.failure",
      "Type" : "Pass"
    },
